CREATE TABLE IF NOT EXISTS transfer_orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), enterprise_id UUID NOT NULL, order_no VARCHAR(100) NOT NULL, source_wh_id UUID NOT NULL, target_wh_id UUID NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'draft', material_id UUID NOT NULL, quantity INT NOT NULL, received_qty INT DEFAULT 0, notes TEXT, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE); CREATE INDEX IF NOT EXISTS idx_to_enterprise ON transfer_orders(enterprise_id); CREATE TABLE IF NOT EXISTS requisitions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), enterprise_id UUID NOT NULL, requisition_no VARCHAR(100) NOT NULL, applicant_id UUID NOT NULL, warehouse_id UUID NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'pending', material_id UUID NOT NULL, quantity INT NOT NULL, issued_qty INT DEFAULT 0, notes TEXT, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE); CREATE INDEX IF NOT EXISTS idx_req_enterprise ON requisitions(enterprise_id);